#!/usr/bin/env python

import rospy
import heapq
from std_msgs.msg import Float32MultiArray
import numpy as np
from threading import Lock
from sklearn.cluster import DBSCAN
from math import fabs, hypot, cos, sin, atan2
from lidar_reconstruction.motion_plan_lib_opt import *

class NavEnv:
    def __init__(self):        
        # subscribe bounding boxes generated by depth clustering method
        self.sub_bounding_boxes = rospy.Subscriber("/bounding_boxes", Float32MultiArray, 
                                                   self.callback_bounding_boxes)
        # subscribe robot pose from LiDAR SLAM algorithm (a-loam)
        self.sub_robot_pose_2d = rospy.Subscriber("/robot/pose2d", Float32MultiArray, 
                                                   self.callback_robot_pose_2d)
        
        # used for process raw bounding boxes and get pedestrian positions
        self.lock_pedestrians = Lock()
        self.pedestrians = []
        self.leg_threshold = 1.5  # if bounding boxes are less than leg_threshold distance to the robot
        self.leg_width = 0.2   # if pedestrians are too close to the robot, only legs are visible
        self.single_human_width = 0.6
        self.bounding_box_data_len = 6

        # used to record robot pose
        self.lock_robot_pose = Lock()
        self.robot_pose = np.zeros(3)
        self.robot_pose_offset = np.array([-0.2, 0.0, 0.0], dtype=np.float32)

        # LiDAR scan environment
        self.nav_dt = 0.2
        self.human_radius = 0.3
        self.frame_stack = 6
        self.robot_goal_state_dim = 4 
        self.action_dim = 2
        self.n_laser = 1800
        self.laser_angle_resolute = 0.003490659
        self.laser_min_range = 0.27
        self.laser_max_range = 6.0
        self.square_width = 10.0
        self.goal = [4.0, 0.0]  # fixed goal
        self.max_human_num = 7
        self.action_last = np.zeros(2)
        self.action_range = np.array([[0.0, -1.0],
                                      [0.5,  1.0]])
    
        # scan_intersection, each line connects the robot and the end of each laser beam
        self.scan_intersection = np.zeros((self.n_laser, 2, 2), dtype=np.float32) # used for visualization

        # laser state
        self.scan_current = self.laser_max_range * np.ones(self.n_laser, dtype=np.float32)
        self.scan_end_current = np.zeros((self.n_laser, 2), dtype=np.float32)

        self.scan_last = np.zeros((self.frame_stack - 1, self.n_laser), dtype=np.float32)
        self.scan_end_last = np.zeros((self.frame_stack - 1, self.n_laser, 2), dtype=np.float32)
        self.lidar_obs = np.zeros((1, self.frame_stack, self.n_laser), dtype=np.float32)

        # log lidar, robot, and humans
        self.global_step = 0
        self.max_episode_step = 250
        self.log_env = {}

    def callback_bounding_boxes(self, msg):
        size = len(msg.data)
        num_bounding_boxes = int(size / self.bounding_box_data_len)
        bounding_boxes = []
        for i in range(num_bounding_boxes):
            bounding_boxes.append(np.array([msg.data[self.bounding_box_data_len * i + 0],
                                            msg.data[self.bounding_box_data_len * i + 1],
                                            msg.data[self.bounding_box_data_len * i + 2],
                                            msg.data[self.bounding_box_data_len * i + 3],
                                            msg.data[self.bounding_box_data_len * i + 4],
                                            msg.data[self.bounding_box_data_len * i + 5]
                                            ], dtype=np.float32))
        all_pedestrians = []
        possible_legs = []
        for i in range(num_bounding_boxes):
            size_x = fabs(bounding_boxes[i][3] - bounding_boxes[i][0])
            size_y = fabs(bounding_boxes[i][4] - bounding_boxes[i][1])
            if (size_x >= self.single_human_width) and (size_y >= self.single_human_width):
                position_x_1 = (bounding_boxes[i][3] + bounding_boxes[i][0]) / 2.0 - size_x / 4.0
                position_x_2 = (bounding_boxes[i][3] + bounding_boxes[i][0]) / 2.0 + size_x / 4.0
                position_y_1 = (bounding_boxes[i][4] + bounding_boxes[i][1]) / 2.0 - size_y / 4.0
                position_y_2 = (bounding_boxes[i][4] + bounding_boxes[i][1]) / 2.0 + size_y / 4.0
                all_pedestrians.append(np.array([position_x_1, position_y_1]))
                all_pedestrians.append(np.array([position_x_1, position_y_2]))
                all_pedestrians.append(np.array([position_x_2, position_y_1]))
                all_pedestrians.append(np.array([position_x_2, position_y_2]))
            elif (size_x >= self.single_human_width) and (size_y < self.single_human_width and size_y >= self.leg_width):
                position_x_1 = (bounding_boxes[i][3] + bounding_boxes[i][0]) / 2.0 - size_x / 4.0
                position_x_2 = (bounding_boxes[i][3] + bounding_boxes[i][0]) / 2.0 + size_x / 4.0
                position_y = (bounding_boxes[i][4] + bounding_boxes[i][1]) / 2.0
                all_pedestrians.append(np.array([position_x_1, position_y]))
                all_pedestrians.append(np.array([position_x_2, position_y]))
            elif (size_x >= self.single_human_width) and (size_y < self.leg_width):
                position_x_1 = (bounding_boxes[i][3] + bounding_boxes[i][0]) / 2.0 - size_x / 4.0
                position_x_2 = (bounding_boxes[i][3] + bounding_boxes[i][0]) / 2.0 + size_x / 4.0
                position_y = (bounding_boxes[i][4] + bounding_boxes[i][1]) / 2.0
                all_pedestrians.append(np.array([position_x_1, position_y]))
                all_pedestrians.append(np.array([position_x_2, position_y]))
            elif (size_x < self.single_human_width and size_x >= self.leg_width) and (size_y >= self.single_human_width):
                position_x = (bounding_boxes[i][3] + bounding_boxes[i][0]) / 2.0
                position_y_1 = (bounding_boxes[i][4] + bounding_boxes[i][1]) / 2.0 - size_y / 4.0
                position_y_2 = (bounding_boxes[i][4] + bounding_boxes[i][1]) / 2.0 + size_y / 4.0
                all_pedestrians.append(np.array([position_x, position_y_1]))
                all_pedestrians.append(np.array([position_x, position_y_2]))
            elif (size_x < self.single_human_width and size_x >= self.leg_width) and (size_y < self.single_human_width and size_y >= self.leg_width):
                position_x = (bounding_boxes[i][3] + bounding_boxes[i][0]) / 2.0
                position_y = (bounding_boxes[i][4] + bounding_boxes[i][1]) / 2.0
                all_pedestrians.append(np.array([position_x, position_y]))
            elif (size_x < self.single_human_width and size_x >= self.leg_width) and (size_y < self.leg_width):
                position_x = (bounding_boxes[i][3] + bounding_boxes[i][0]) / 2.0
                position_y = (bounding_boxes[i][4] + bounding_boxes[i][1]) / 2.0
                all_pedestrians.append(np.array([position_x, position_y]))
            elif (size_x < self.leg_width) and (size_y >= self.single_human_width):
                position_x = (bounding_boxes[i][3] + bounding_boxes[i][0]) / 2.0
                position_y_1 = (bounding_boxes[i][4] + bounding_boxes[i][1]) / 2.0 - size_y / 4.0
                position_y_2 = (bounding_boxes[i][4] + bounding_boxes[i][1]) / 2.0 + size_y / 4.0
                all_pedestrians.append(np.array([position_x, position_y_1]))
                all_pedestrians.append(np.array([position_x, position_y_2]))
            elif (size_x < self.leg_width) and (size_y < self.single_human_width and size_y >= self.leg_width):
                position_x = (bounding_boxes[i][3] + bounding_boxes[i][0]) / 2.0
                position_y = (bounding_boxes[i][4] + bounding_boxes[i][1]) / 2.0
                all_pedestrians.append(np.array([position_x, position_y]))
            elif (size_x < self.leg_width) and (size_y < self.leg_width):
                position_x = (bounding_boxes[i][3] + bounding_boxes[i][0]) / 2.0
                position_y = (bounding_boxes[i][4] + bounding_boxes[i][1]) / 2.0
                distance_robot = hypot(position_x - self.robot_pose[0], position_y - self.robot_pose[1])
                if distance_robot < self.leg_threshold:
                    possible_legs.append(np.array([position_x, position_y], dtype=np.float32))
                else:
                    all_pedestrians.append(np.array([position_x, position_y]))
        num_possible_legs = len(possible_legs)
        if num_possible_legs == 1:
            position_x = (bounding_boxes[i][3] + bounding_boxes[i][0]) / 2.0
            position_y = (bounding_boxes[i][4] + bounding_boxes[i][1]) / 2.0
            all_pedestrians.append(np.array([position_x, position_y]))
        elif num_possible_legs > 1:
            numpy_possible_legs = np.array(possible_legs)
            # Run DBSCAN to cluster
            db = DBSCAN(eps=self.leg_width*2, min_samples=1).fit(numpy_possible_legs)
            labels = db.labels_   

            unique_labels = np.unique(labels)
            for label in unique_labels:
                cluster_points = numpy_possible_legs[labels == label]
                center = np.mean(cluster_points, axis=0)
                all_pedestrians.append(center)
                
        self.lock_pedestrians.acquire()
        if len(all_pedestrians) <= self.max_human_num:
            self.pedestrians = all_pedestrians
        else:
            dis_all = []
            for ped in all_pedestrians:
                dis = hypot(ped[0] - self.robot_pose[0], ped[1] - self.robot_pose[1])
                dis_all.append(dis)
            # Find the self.max_human_num smallest values and their indexes
            smallest = heapq.nsmallest(self.max_human_num, enumerate(dis_all), key=lambda x: x[1])
            # Separate indexes and values
            indexes = [i for i, v in smallest]
            self.pedestrians = [all_pedestrians[j] for j in indexes]
        self.lock_pedestrians.release()
        
    def callback_robot_pose_2d(self, msg):
        self.lock_robot_pose.acquire()
        self.robot_pose[0] = msg.data[0]
        self.robot_pose[1] = msg.data[1]
        self.robot_pose[2] = msg.data[2]
        self.lock_robot_pose.release()

    '''use c library to generate lidar scan, which is fast'''
    def get_lidar(self, robot_pose_transform, pedestrians_real, isReset=False):
        num_circle_human = len(pedestrians_real)
        robot_pose_new = np.array([robot_pose_transform[0], robot_pose_transform[1], robot_pose_transform[2]], dtype=np.float32)
        human_circles = -100.0 * np.ones((self.max_human_num, 3), dtype=np.float32)
        for i in range(num_circle_human):
            human_circles[i] = np.array([pedestrians_real[i][0], pedestrians_real[i][1], self.human_radius], dtype=np.float32)
        self.log_env['humans'][self.global_step] = human_circles
        scans_raw, scan_lines = cal_laser(human_circles, robot_pose_new)

        self.scan_intersection = np.zeros((self.n_laser, 2, 2), dtype=np.float32)
        scan_end = np.zeros((self.n_laser, 2), dtype=np.float32)
        for i in range(self.n_laser):
            ### used for visualization
            self.scan_intersection[i, 0, 0] = scan_lines[i, 0]
            self.scan_intersection[i, 0, 1] = scan_lines[i, 1]
            self.scan_intersection[i, 1, 0] = scan_lines[i, 2]
            self.scan_intersection[i, 1, 1] = scan_lines[i, 3]
            scan_end[i, :] = np.array([self.scan_intersection[i, 1, 0], self.scan_intersection[i, 1, 1]])
            ### used for visualization
        self.scan_current = np.clip(scans_raw, self.laser_min_range, self.laser_max_range)
        if isReset:
            self.scan_end_current = np.copy(scan_end)
            for frame_idx in range(self.frame_stack - 1):
                self.scan_last[frame_idx] = np.copy(self.scan_current)
                self.scan_end_last[frame_idx] = np.copy(self.scan_end_current)
        else:
            # t1 = time()
            scan_last_raw = transform_scan_last(self.scan_end_last, robot_pose_new)   
            # print('time: ', time() - t1)
            self.scan_last = np.clip(scan_last_raw, self.laser_min_range, self.laser_max_range)      
            for frame_idx in range(self.frame_stack - 2):
                self.scan_end_last[self.frame_stack - frame_idx - 2] = np.copy(self.scan_end_last[self.frame_stack - frame_idx - 3])
            self.scan_end_current = np.copy(scan_end)
            self.scan_end_last[0] = np.copy(self.scan_end_current)
            
        lidar_obs = np.hstack((self.scan_current, self.scan_last.flatten()))
        self.lidar_obs = np.reshape(lidar_obs, (1, self.frame_stack, self.n_laser))

    def get_robot_goal_state(self, robot_pose_transform):
        dx = self.goal[0] - robot_pose_transform[0]
        dy = self.goal[1] - robot_pose_transform[1]
        theta = robot_pose_transform[2]
        y_rel = dy * cos(theta) - dx * sin(theta)
        x_rel = dy * sin(theta) + dx * cos(theta)
        r = hypot(x_rel, y_rel)
        t = atan2(y_rel, x_rel)
        
        robot_goal_state = np.array([r / self.square_width, t / np.pi, 
                                     self.action_last[0] / self.action_range[1, 0],
                                     self.action_last[1] / self.action_range[1, 1]], dtype=np.float32)
        
        return robot_goal_state

    def get_obs(self, action):
        robot_pose_real = self.robot_pose
        robot_pose_transform = robot_pose_real + self.robot_pose_offset
        pedestrians_real = self.pedestrians
        self.get_lidar(robot_pose_transform, pedestrians_real, self.global_step == 0)
        robot_goal_state = self.get_robot_goal_state(robot_pose_transform)
        self.action_last = action
        
        self.log_env['robot'][self.global_step] = np.array([robot_pose_transform[0], 
                                                            robot_pose_transform[1], 
                                                            action[0], action[1], 
                                                            robot_pose_transform[2]])
        self.log_env['goal'][self.global_step] = np.array([self.goal[0], self.goal[1]])
       
        lasers = np.zeros((self.n_laser, 4), dtype=np.float32)
        for i in range(self.n_laser):
            laser = self.scan_intersection[i]
            lasers[i] = np.array([laser[0][0], laser[0][1], laser[1][0], laser[1][1]], dtype=np.float32)
        self.log_env['laser'][self.global_step] = lasers

        self.global_step = self.global_step + 1
        return self.lidar_obs / self.laser_max_range, robot_goal_state

    def reset_nav_env(self):
        self.global_step = 0
        self.action_last = np.zeros(2)
        
        self.log_env['robot'] = -100.0 * np.ones((self.max_episode_step + 1, 5), dtype=np.float32)
        self.log_env['goal'] =  -100.0 * np.ones((self.max_episode_step + 1, 2), dtype=np.float32)
        self.log_env['humans'] = -100.0 * np.ones((self.max_episode_step + 1, self.max_human_num, 3), dtype=np.float32)
        self.log_env['laser'] = -100.0 * np.ones((self.max_episode_step + 1, self.n_laser, 4), dtype=np.float32)
        

